// === Tab: mySketch ===
// created based off the Shaders tutorial by @Oren Shoham

let currentShader;
let graphic;
let font;
let paused = false;

function preload() {
  currentShader = getShader(this._renderer);
  font = loadFont('https://openprocessing.org/sketch/2616721/files/Sohne-Fett.otf');
}

function setup() {
  createCanvas(windowWidth, windowHeight, WEBGL);
  noStroke();

  // ------------ create graphic with text ------------------ //
  graphic = createGraphics(windowWidth, windowHeight);
  graphic.background(0, 0, 255);
  graphic.noStroke();
  graphic.textFont(font);
  graphic.textSize(windowWidth * 0.2);
  graphic.textAlign(CENTER, CENTER);
  graphic.fill(0, 255, 0);
  graphic.stroke(0);
  graphic.strokeWeight(0);
  graphic.text('caffeine', windowWidth * 0.5, windowHeight * 0.5);

  shader(currentShader);
  currentShader.setUniform('tex', graphic);
}

function draw() {
  if (!paused) {
    let freq = map((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), 0, width, 0, 10.0);
    let amp = map((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 0, height, 0, 0.25);

    currentShader.setUniform('frequency', freq);
    currentShader.setUniform('amplitude', amp);
    currentShader.setUniform('speed', frameCount * 0.02);
  }

  rect(0, 0, width, height);
}

function mousePressed() {
  paused = !paused;
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);

  graphic = createGraphics(windowWidth, windowHeight);
  graphic.background(0, 0, 255);
  graphic.noStroke();
  graphic.textFont(font);
  graphic.textSize(windowWidth * 0.2);
  graphic.textAlign(CENTER, CENTER);
  graphic.fill(0, 255, 0);
  graphic.stroke(0);
  graphic.strokeWeight(0);
  graphic.text('caffeine', windowWidth * 0.5, windowHeight * 0.5);

  currentShader.setUniform('tex', graphic);
}

function mouseWheel() {
  return false;
}


// === Tab: shader ===
function getShader(_renderer) {
	const vert = `
		attribute vec3 aPosition;
		attribute vec2 aTexCoord;

		varying vec2 vUV;

		void main() {
			vUV = aTexCoord;

			vec4 position = vec4(aPosition, 1.0);
			position.xy = position.xy * 2.0 - 1.0;
			gl_Position = position;
		}
	`;

	const frag = `
		precision highp float;

		varying vec2 vUV;

		uniform sampler2D tex;
		uniform float speed;
		uniform float frequency;
		uniform float amplitude;

		void main() {
			vec2 uv = vec2(1.0, 1.0) - vUV;
			//flip the image so its the right way around
			uv.x = uv.x * -1.0;

			// lets create a sine wave to distort our texture coords
			// we will use the built in sin() function in glsl
			// sin() returns the sine of an angle in radians
			// first will multiply our uv * frequency -- frequency will control how many hills and valleys will be in the wave
			// then we add some time to our sine, this will make it move 
			// lastly multiply the whole thing by amplitude -- amplitude controls how tall the hills and valleys are, in this case it will be how much to distort the image
			// *try changing uv.y to uv.x and see what happens

			float sineWave = sin(uv.y * frequency + speed) * amplitude;

			// create a vec2 with our sine
			// what happens if you put sineWave in the y slot? in Both slots?
			vec2 distort = vec2(sineWave, sineWave);

			// use mod() to wrap our texcoords back to 0.0 if they go over 1.0
			vec4 texColor = texture2D(tex, mod(uv - distort, 1.0));

			gl_FragColor = texColor;
		}
	`;

	return createShader(vert, frag);
}

